import { Children, type ReactElement, type ReactNode, useMemo } from "react";
import Animated, { useAnimatedStyle } from "react-native-reanimated";
import { useThemeColor } from "@registry/hooks/use-theme-color";
import { IconDefaultsProvider } from "@registry/ui/icon";
import { Text } from "@registry/ui/text";
import { TextClassProvider } from "@registry/ui/text/text.context";
import { useSwitchPart } from "./switch.context";
import type { SwitchContentProps } from "./switch.types";
import { resolveSwitchContentTreatment, type SwitchContentPlacement, switchVariants } from "./switch.variants";

/**
 * The shared implementation behind `Switch.StartContent` and `.EndContent`.
 *
 * The two are the same box at opposite ends of the track — which end, and which
 * way their opacity runs, are the only differences — so they share this leaf
 * rather than duplicating {@link wrapTextChildren} and an animated style into
 * two part files. `Input.Group`'s two decorators make the same trade.
 *
 * **The crossfade is the component's, not the caller's.** `StartContent` sits at
 * the leading edge, which the thumb vacates as the switch turns **on**, so it
 * fades in with `progress`; `EndContent` sits at the trailing edge and fades out
 * with it. That is what lets both be written once with no conditionals — the
 * thumb reads as uncovering the other end rather than as sliding over content
 * that was always there.
 *
 * The layer is exactly the thumb's footprint at its own end, so a glyph is
 * centred on the space the knob will vacate rather than beside it.
 *
 * Not a part itself: it takes the caller-facing name so the error thrown outside
 * a switch names `Switch.StartContent` rather than something private.
 */
export function SwitchContent({
	part,
	placement,
	className,
	children,
	...props
}: SwitchContentProps & { part: string; placement: SwitchContentPlacement }): ReactElement {
	const { color, size, isDisabled, isInvalid, progress } = useSwitchPart(part);
	const slots = switchVariants({ isDisabled, size });

	const treatment = resolveSwitchContentTreatment({ color, isInvalid, placement });
	const glyphColor = useThemeColor(treatment.color);
	const glyphClassName = slots.glyph();
	const iconDefaults = useMemo(
		() => ({ className: glyphClassName, color: glyphColor ?? "" }),
		[glyphClassName, glyphColor]
	);

	const isStart = placement === "start";
	const contentStyle = useAnimatedStyle(() => ({
		opacity: isStart ? progress.value : 1 - progress.value,
	}));

	const textClassName = slots.contentText({ className: treatment.textClass });

	return (
		<Animated.View
			className={isStart ? slots.startContent({ className }) : slots.endContent({ className })}
			// Never the element a screen reader lands on. The switch announces itself
			// as one control with a checked state, and a decorative glyph either side
			// of the knob has nothing to add to that.
			accessible={false}
			importantForAccessibility="no-hide-descendants"
			pointerEvents="none"
			style={contentStyle}
			{...props}
		>
			<IconDefaultsProvider value={iconDefaults}>
				<TextClassProvider value={textClassName}>{wrapTextChildren(children)}</TextClassProvider>
			</IconDefaultsProvider>
		</Animated.View>
	);
}
SwitchContent.displayName = "DelacourUI.Switch.Content";

/**
 * Wraps bare text children in a `Text`.
 *
 * A content layer renders a `View`, and React Native cannot render a string
 * outside a `<Text>` — so `<Switch.EndContent>OFF</Switch.EndContent>`, which is
 * the shortest thing anyone will write, would otherwise crash. Consecutive
 * strings and numbers collapse into one `Text` rather than one each, the same
 * rule and the same reason as `Input`'s decorators.
 *
 * The wrapped text needs no className: the layer has already published its
 * treatment through `TextClassProvider`.
 */
function wrapTextChildren(children: ReactNode): ReactNode {
	const items = Children.toArray(children);
	const output: ReactNode[] = [];
	let run: (string | number)[] = [];

	const flushRun = () => {
		if (run.length === 0) return;
		output.push(<Text key={`content-${output.length}`}>{run.join("")}</Text>);
		run = [];
	};

	for (const child of items) {
		if (typeof child === "string" || typeof child === "number") {
			run.push(child);
			continue;
		}
		flushRun();
		output.push(child);
	}
	flushRun();

	return output;
}

import type { ReactElement } from "react";
import type { SwitchContentProps } from "./switch.types";
import { SwitchContent } from "./switch-content";

/**
 * Content at the trailing edge of the track, behind the thumb.
 *
 * Revealed as the switch turns **off** — this is the end the knob vacates — so
 * it is where the "off" mark goes: a cross, a moon, the word OFF. The fade is
 * the component's, so write it once and unconditionally.
 *
 * It sits on the resting track rather than the coloured one, so its glyph takes
 * a muted foreground rather than the switch's colour.
 */
export function SwitchEndContent(props: SwitchContentProps): ReactElement {
	return <SwitchContent part="Switch.EndContent" placement="end" {...props} />;
}
SwitchEndContent.displayName = "DelacourUI.Switch.EndContent";

import type { ReactElement } from "react";
import type { SwitchContentProps } from "./switch.types";
import { SwitchContent } from "./switch-content";

/**
 * Content at the leading edge of the track, behind the thumb.
 *
 * Revealed as the switch turns **on** — this is the end the knob vacates — so it
 * is where the "on" mark goes: a tick, a sun, the word ON. The fade is the
 * component's, so write it once and unconditionally; there is no `isSelected &&`
 * to remember.
 *
 * An `Icon` needs nothing said at the call site: it inherits the switch's glyph
 * step and the foreground of the colour the track fades to. A bare string is
 * wrapped in a `Text` that inherits the same treatment.
 */
export function SwitchStartContent(props: SwitchContentProps): ReactElement {
	return <SwitchContent part="Switch.StartContent" placement="start" {...props} />;
}
SwitchStartContent.displayName = "DelacourUI.Switch.StartContent";

import { type ReactElement, type ReactNode, useCallback, useMemo } from "react";
import type { LayoutChangeEvent, ViewProps } from "react-native";
import Animated, { interpolateColor, useAnimatedStyle } from "react-native-reanimated";
import { useThemeColor } from "@registry/hooks/use-theme-color";
import { IconDefaultsProvider } from "@registry/ui/icon";
import { useSwitchPart } from "./switch.context";
import {
	resolveSwitchThumbTokens,
	resolveSwitchTrackTokens,
	SWITCH_THUMB_INSET,
	switchTravel,
	switchVariants,
} from "./switch.variants";

export type SwitchThumbProps = Omit<ViewProps, "children" | "style"> & {
	className?: string;
	/** Drawn inside the knob. An `Icon` needs nothing said at the call site. */
	children?: ReactNode;
};

/**
 * The knob that slides between the two ends of the track.
 *
 * Composed in automatically when the children hold none, so `<Switch />` is
 * already a complete control — `Radio`'s rule for its indicator. Write it out by
 * hand only to restyle it, or to put a glyph inside it.
 *
 * **It holds no gesture of its own.** One `Gesture.Pan()` on the root drives it,
 * because a touch anywhere on the pill should move the knob it is about to
 * move — and a gesture here would nest a descendant recogniser inside the root's,
 * leaving two to negotiate for one drag. `Slider.Thumb` makes the same trade for
 * the same reason.
 *
 * **One animated style, one node.** The position and the colour are entries in a
 * single `useAnimatedStyle`, because two calls on one view fight for the same
 * props and the later one silently wins — the rule `Radio.Indicator` states.
 *
 * **The colour is not a class.** It fades between two token *values* as the
 * switch travels, and a colour being interpolated cannot be a class — the rule
 * `Checkbox`'s border already follows. The `thumb` slot keeps `bg-background` as
 * the resting appearance this style starts from, and nothing else names a
 * background; two sources for one surface is how a class and a style end up
 * disagreeing for a frame on every toggle.
 *
 * **It is invisible until both layouts have reported.** The travel is measured,
 * not tabulated — `size-icon-xl` cannot be read from JavaScript — and a knob
 * drawn before then sits at a garbage offset for a frame, which reads as a
 * flicker on every mount.
 *
 * **It does not scale when grabbed, and the track does instead.** The track
 * clips, so a scaled knob would be cut off by its own capsule — a bite taken out
 * of the knob rather than an acknowledgement of the press. The outermost node is
 * the one thing nothing can crop, so that is where the press feedback lives.
 */
export function SwitchThumb({ className, children, ...props }: SwitchThumbProps): ReactElement {
	const { color, size, isInvalid, isDisabled, progress, trackWidth, thumbWidth } = useSwitchPart("Switch.Thumb");

	const handleLayout = useCallback(
		(event: LayoutChangeEvent) => {
			thumbWidth.value = event.nativeEvent.layout.width;
		},
		[thumbWidth]
	);

	const tokens = resolveSwitchThumbTokens({ color, isInvalid });
	const restColor = useThemeColor(tokens.rest) ?? "transparent";
	const activeColor = useThemeColor(tokens.active) ?? "transparent";

	const thumbStyle = useAnimatedStyle(() => {
		const measured = trackWidth.value;
		const travel = switchTravel({
			inset: SWITCH_THUMB_INSET,
			thumbWidth: thumbWidth.value,
			trackWidth: measured,
		});

		return {
			backgroundColor: interpolateColor(progress.value, [0, 1], [restColor, activeColor]),
			opacity: measured > 0 ? 1 : 0,
			transform: [{ translateX: progress.value * travel }],
		};
	});

	// A glyph on the knob takes the *track*'s colour, not the knob's own: it is
	// drawn on the knob, so it has to contrast with it, and the one value that
	// reads at both ends is the colour the track fades to. Static rather than
	// interpolated because an `Icon`'s colour is a prop, not a style.
	const slots = switchVariants({ isDisabled, size });
	const glyphColor = useThemeColor(resolveSwitchTrackTokens({ color, isInvalid }).active);
	const glyphClassName = slots.glyph();
	const iconDefaults = useMemo(
		() => ({ className: glyphClassName, color: glyphColor ?? "" }),
		[glyphClassName, glyphColor]
	);

	return (
		<Animated.View className={slots.thumb({ className })} onLayout={handleLayout} style={thumbStyle} {...props}>
			{children ? <IconDefaultsProvider value={iconDefaults}>{children}</IconDefaultsProvider> : null}
		</Animated.View>
	);
}
SwitchThumb.displayName = "DelacourUI.Switch.Thumb";

import { createContext, type ReactElement, type ReactNode, use } from "react";
import type { SharedValue } from "react-native-reanimated";
import type { SwitchColor, SwitchSize } from "./switch.variants";

export type SwitchContextValue = {
	color: SwitchColor;
	size: SwitchSize;
	/** Whether the switch is on, on the **JS thread** — what accessibility reads. */
	isSelected: boolean;
	isDisabled: boolean;
	isInvalid: boolean;
	/**
	 * Where the thumb is, on the **UI thread**: `0` at the leading edge, `1` at
	 * the trailing one.
	 *
	 * The one value every animated style on this control reads — the thumb's
	 * position and colour, the track's colour, and both content layers' opacity.
	 * One source rather than four, so they cannot drift out of step by a frame.
	 *
	 * It agrees with {@link SwitchContextValue.isSelected} at rest and disagrees
	 * for the whole of a drag, which is the entire reason the drag never waits on
	 * React.
	 */
	progress: SharedValue<number>;
	/** The track's own width, from its `onLayout`. `0` until it has been measured. */
	trackWidth: SharedValue<number>;
	/** The thumb's width, from its `onLayout`. `0` until it has been measured. */
	thumbWidth: SharedValue<number>;
};

const SwitchContext = createContext<SwitchContextValue | null>(null);

/**
 * Supplies one switch's settled state and shared values to its own parts.
 *
 * Lives in its own module, importing nothing but React and types, so a part can
 * read it without importing `./switch`. That import would close a cycle, and
 * Metro serves a partially initialised module for a cycle — leaving the context
 * `undefined` at import time and red-boxing the app on a cold start.
 */
export function SwitchProvider({ value, children }: { value: SwitchContextValue; children: ReactNode }): ReactElement {
	return <SwitchContext value={value}>{children}</SwitchContext>;
}
SwitchProvider.displayName = "DelacourUI.Switch.Provider";

/** The enclosing switch's state, or null outside a `<Switch>`. */
export function useSwitchContext(): SwitchContextValue | null {
	return use(SwitchContext);
}

/**
 * Reads the enclosing switch's settled state.
 *
 * Lets a custom child style itself to match without the switch having to pass
 * props down through every slot. Throws outside a `<Switch>` — use
 * {@link useSwitchContext} where the enclosing switch is optional.
 */
export function useSwitch(): SwitchContextValue {
	const context = useSwitchContext();
	if (!context) {
		throw new Error("useSwitch must be called inside a <Switch>.");
	}
	return context;
}

/**
 * The enclosing switch's state, for a compound part that cannot work without one.
 *
 * Internal: deliberately not re-exported from `index.ts`. A caller outside the
 * library wants {@link useSwitch}, whose error message names the hook rather
 * than a part.
 */
export function useSwitchPart(component: string): SwitchContextValue {
	const context = useSwitchContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside a <Switch>.`);
	}
	return context;
}

import {
	Children,
	isValidElement,
	type ReactElement,
	type ReactNode,
	useCallback,
	useEffect,
	useMemo,
	useRef,
	useState,
} from "react";
import type { AccessibilityActionEvent, LayoutChangeEvent, ViewProps } from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
	cancelAnimation,
	interpolateColor,
	useAnimatedStyle,
	useSharedValue,
	withSpring,
} from "react-native-reanimated";
import { scheduleOnRN } from "react-native-worklets";
import { useControllableState } from "@registry/hooks/use-controllable-state";
import { useThemeColor } from "@registry/hooks/use-theme-color";
import { useFieldContext } from "@registry/ui/field/field.context";
import { type HapticFeedback, playHaptic } from "@registry/ui/pressable";
import { type SwitchContextValue, SwitchProvider } from "./switch.context";
import {
	hasThumbChild,
	resolveSwitchAxes,
	resolveSwitchRelease,
	resolveSwitchTrackTokens,
	SWITCH_PRESS_ANIMATION,
	SWITCH_PRESS_SPRING,
	SWITCH_THUMB_INSET,
	SWITCH_THUMB_SPRING,
	type SwitchColor,
	type SwitchSize,
	switchTravel,
	switchVariants,
} from "./switch.variants";
import { SwitchEndContent } from "./switch-end-content";
import { SwitchStartContent } from "./switch-start-content";
import { SwitchThumb } from "./switch-thumb";

export type SwitchProps = Omit<ViewProps, "children" | "style"> & {
	/** Controlled state. Pass nothing and the switch holds its own. */
	isSelected?: boolean;
	/** Starting state while uncontrolled. */
	defaultSelected?: boolean;
	onSelectedChange?: (isSelected: boolean) => void;
	/** What a switch that is on means. */
	color?: SwitchColor;
	size?: SwitchSize;
	/** Blocks the gesture and fades the control. Inherited from an enclosing `Field`. */
	isDisabled?: boolean;
	/** Reports an invalid value. Inherited from an enclosing `Field`. */
	isInvalid?: boolean;
	/** Played when a press or a drag actually flips it. `false` silences it. */
	haptic?: false | HapticFeedback;
	className?: string;
	children?: ReactNode;
};

function SwitchRoot({
	isSelected,
	defaultSelected = false,
	onSelectedChange,
	color,
	size,
	isDisabled,
	isInvalid,
	haptic = "selection",
	className,
	children,
	...props
}: SwitchProps): ReactElement {
	const field = useFieldContext();
	const axes = resolveSwitchAxes({ field, own: { color, isDisabled, isInvalid, size } });

	const [selected, setSelected] = useControllableState({
		defaultValue: defaultSelected,
		onChange: onSelectedChange,
		value: isSelected,
	});

	// Seeded from the current state rather than from zero, so a switch mounted on
	// does not slide its thumb across on its first paint.
	const progress = useSharedValue(selected ? 1 : 0);
	const trackWidth = useSharedValue(0);
	const thumbWidth = useSharedValue(0);
	// Where the thumb was when the finger landed, so a drag is relative to the
	// grab rather than to the leading edge — picking up a half-travelled thumb
	// mid-spring does not snap it to the finger.
	const grabbed = useSharedValue(0);
	// Whether a finger is down, driving the track's press scale. A shared value
	// rather than state: nothing renders differently for it, so a commit on every
	// touch would be pure cost.
	const isPressed = useSharedValue(0);

	// A ref rather than state: the pan reads it twice a drag and nothing renders
	// differently for it, so a re-render on touch-down would be pure cost.
	const isDragging = useRef(false);
	// Bumped on every release, purely to make the sync effect below run again.
	const [settledDrags, setSettledDrags] = useState(0);

	// `settledDrags` is not read in the body — being unread is the whole point of
	// it. A controlled parent that *rejects* a dragged value leaves `selected`
	// unchanged, so without a token that moves on every release there is nothing
	// to re-run on, and the thumb stays where the finger let go rather than
	// springing back to the state the parent actually holds.
	// biome-ignore lint/correctness/useExhaustiveDependencies: the extra dependency is the re-run trigger, see above
	useEffect(() => {
		if (isDragging.current) return;
		progress.value = withSpring(selected ? 1 : 0, SWITCH_THUMB_SPRING);

		// Without this a switch unmounted mid-travel leaves its spring running.
		return () => cancelAnimation(progress);
	}, [progress, selected, settledDrags]);

	const setDragging = useCallback((dragging: boolean) => {
		isDragging.current = dragging;
	}, []);

	const selectedRef = useRef(selected);
	selectedRef.current = selected;

	const commit = useCallback(
		(next: boolean) => {
			setSettledDrags((count) => count + 1);
			if (next !== selectedRef.current) setSelected(next);
		},
		[setSelected]
	);

	const handleLayout = useCallback(
		(event: LayoutChangeEvent) => {
			trackWidth.value = event.nativeEvent.layout.width;
		},
		[trackWidth]
	);

	const gesture = useMemo(
		() =>
			Gesture.Pan()
				.enabled(!axes.isDisabled)
				.minDistance(0)
				.shouldCancelWhenOutside(false)
				.onBegin(() => {
					"worklet";
					grabbed.value = progress.value;
					isPressed.value = withSpring(1, SWITCH_PRESS_SPRING);
					scheduleOnRN(setDragging, true);
				})
				.onUpdate((event) => {
					"worklet";
					const travel = switchTravel({
						inset: SWITCH_THUMB_INSET,
						thumbWidth: thumbWidth.value,
						trackWidth: trackWidth.value,
					});
					if (travel <= 0) return;

					progress.value = Math.min(1, Math.max(0, grabbed.value + event.translationX / travel));
				})
				.onFinalize((event) => {
					"worklet";
					// Whichever axis moved further. A vertical swipe that began on the
					// switch has to count as movement, or every attempt to scroll past
					// the control would read as a tap and toggle it.
					const target = resolveSwitchRelease({
						distance: Math.max(Math.abs(event.translationX), Math.abs(event.translationY)),
						progress: progress.value,
						velocity: event.velocityX,
						wasSelected: selected,
					});

					progress.value = withSpring(target ? 1 : 0, SWITCH_THUMB_SPRING);
					isPressed.value = withSpring(0, SWITCH_PRESS_SPRING);
					// At the commit, never at the grab. A drag taken half way and
					// released back has changed nothing, and a switch that buzzed for it
					// would be reporting a state change that did not happen.
					if (haptic !== false && target !== selected) playHaptic(haptic);

					// Order matters: the root must have stopped treating this as a live
					// drag before `commit` asks it to re-sync. `scheduleOnRN` keeps them
					// in the order they were queued.
					scheduleOnRN(setDragging, false);
					scheduleOnRN(commit, target);
				}),
		[axes.isDisabled, commit, grabbed, haptic, isPressed, progress, selected, setDragging, thumbWidth, trackWidth]
	);

	const toggle = useCallback(() => {
		commit(!selectedRef.current);
	}, [commit]);

	// Offered to an enclosing `Field` so tapping the label or the description
	// beside the switch flips it. A switch in a form is a small pill next to a
	// sentence, and the sentence is what people aim at.
	//
	// Registered through a ref-backed trampoline rather than `toggle` itself, the
	// way `Checkbox` does it: re-registering whenever the state changed would
	// re-render the whole field for nothing.
	const toggleRef = useRef(toggle);
	toggleRef.current = toggle;
	const registerPress = field?.registerPress;
	const stableToggle = useCallback(() => toggleRef.current(), []);

	useEffect(() => {
		if (!registerPress) return;
		registerPress(stableToggle);
		return () => registerPress(null);
	}, [registerPress, stableToggle]);

	const trackTokens = resolveSwitchTrackTokens({ color: axes.color, isInvalid: axes.isInvalid });
	const restColor = useThemeColor(trackTokens.rest) ?? "transparent";
	const activeColor = useThemeColor(trackTokens.active) ?? "transparent";

	// One animated style on one node: the colour the switch travels through and
	// the press scale are two entries here rather than two `useAnimatedStyle`
	// calls, because two on one view fight for the same props and the later one
	// silently wins — the rule `Radio.Indicator` states.
	//
	// The colour interpolates off `progress` rather than running a timing of its
	// own against `selected`, so the track colours *with the finger* through a
	// drag instead of snapping when it is let go. A separate timing would also be
	// a second clock the position could drift from.
	const trackStyle = useAnimatedStyle(() => ({
		backgroundColor: interpolateColor(progress.value, [0, 1], [restColor, activeColor]),
		transform: [
			{
				scale:
					SWITCH_PRESS_ANIMATION.restScale -
					isPressed.value * (SWITCH_PRESS_ANIMATION.restScale - SWITCH_PRESS_ANIMATION.pressedScale),
			},
		],
	}));

	const context = useMemo<SwitchContextValue>(
		() => ({
			color: axes.color,
			isDisabled: axes.isDisabled,
			isInvalid: axes.isInvalid,
			isSelected: selected,
			progress,
			size: axes.size,
			thumbWidth,
			trackWidth,
		}),
		[axes.color, axes.isDisabled, axes.isInvalid, axes.size, progress, selected, thumbWidth, trackWidth]
	);

	const content = useMemo(() => withThumb(children), [children]);
	const slots = switchVariants({ isDisabled: axes.isDisabled, size: axes.size });

	const handleAccessibilityAction = useCallback(
		(event: AccessibilityActionEvent) => {
			if (event.nativeEvent.actionName === "activate") toggle();
		},
		[toggle]
	);

	return (
		<SwitchProvider value={context}>
			<GestureDetector gesture={gesture}>
				<Animated.View
					accessibilityActions={ACCESSIBILITY_ACTIONS}
					accessibilityRole="switch"
					accessibilityState={{ checked: selected, disabled: axes.isDisabled }}
					// Without this the view is not an accessibility element on iOS, and
					// the role and the state above never reach VoiceOver. It also merges
					// the parts into one element, which is what a control should be.
					accessible
					className={slots.touchArea({ className })}
					onAccessibilityAction={handleAccessibilityAction}
					onAccessibilityTap={toggle}
					{...props}
				>
					<Animated.View className={slots.track()} onLayout={handleLayout} style={trackStyle}>
						{content}
					</Animated.View>
				</Animated.View>
			</GestureDetector>
		</SwitchProvider>
	);
}

/**
 * The one action an assistive double-tap on a `switch` maps to.
 *
 * Module scope on purpose: a fresh array each render is a new prop every commit,
 * and React Native sends the whole accessibility config across on any change.
 *
 * It exists at all because the root is not a `Pressable` — there is no touch
 * responder for TalkBack's activation to land on, so without this the switch
 * would announce its state and offer no way to change it. `onAccessibilityTap`
 * is the iOS half of the same gap.
 */
const ACCESSIBILITY_ACTIONS = [{ name: "activate" }] as const;

/**
 * Composes a `Switch.Thumb` in, and puts it last however it was written.
 *
 * Composed in when the children hold none, so `<Switch />` on its own is already
 * a complete control — `Radio`'s rule for its indicator, and the same reasoning:
 * a switch has exactly one thumb, so a caller who wrote none wants the default
 * rather than an empty capsule.
 *
 * **Moved to the end when they did write one.** Every part here is absolutely
 * positioned, and React Native paints later siblings on top — so a thumb written
 * first, which is the order the anatomy reads best in, would slide *under* the
 * content layers. Reordering here rather than asking the caller to is the
 * difference between an anatomy that documents itself and one that has a gotcha.
 *
 * {@link hasThumbChild} is the decision and is pure, so `bun test` reaches it.
 *
 * Lives here rather than with the parts: it is the root that arranges its own
 * children, and importing it from a part would close a cycle. See AGENTS.md.
 */
function withThumb(children: ReactNode): ReactNode {
	const items = Children.toArray(children);
	const isThumb = items.map(isSwitchThumbElement);

	if (!hasThumbChild(isThumb)) return [...items, <SwitchThumb key="thumb" />];

	return [...items.filter((_, index) => !isThumb[index]), ...items.filter((_, index) => isThumb[index])];
}

/**
 * Whether a child is a `Switch.Thumb`.
 *
 * **Reference equality is asked first and is not trusted alone.** A consuming
 * app compiles this package's source itself — the package ships raw `.tsx` — so
 * the function this module holds and the one behind a caller's `<Switch.Thumb>`
 * are only the same object while nothing has rewritten the binding in between.
 * React Compiler does exactly that, and Metro can serve two instances of one
 * module through a workspace symlink; either leaves an element whose `type` is a
 * different object standing for the same component.
 *
 * The failure is silent and specific: detection returns false, a second thumb is
 * composed in on top of the caller's, and because the two are the same size and
 * colour the only visible symptom is that anything *inside* the caller's knob
 * disappears under the default one. It cost an afternoon to find, which is why
 * the check no longer rests on identity.
 *
 * `displayName` is what it rests on instead. Rule 12 requires every component in
 * this package to carry one, `display-name.test.ts` enforces that they are
 * present and unique, and it survives every rewrite above because it is a
 * property assigned to the function rather than the function itself. Read off
 * the element's own `type`, which is a function today and would be an object if
 * this part were ever wrapped in `memo`.
 */
function isSwitchThumbElement(child: ReactNode): boolean {
	if (!isValidElement(child)) return false;
	if (child.type === SwitchThumb) return true;

	const type = child.type as { displayName?: string } | null;
	return type?.displayName !== undefined && type.displayName === SwitchThumb.displayName;
}

/**
 * A binary preference, flipped by a tap or by dragging its thumb.
 *
 * The whole pill is the control and one `Gesture.Pan()` drives it: a tap toggles,
 * a drag takes the thumb with the finger, and a release settles by position or by
 * a flick's velocity. There is no separate tap mode — a release that barely moved
 * *is* the tap, which is why the two never race.
 *
 * A `Switch.Thumb` is composed in when the children hold none, so `<Switch />` is
 * already complete. Anything else composed inside lands *behind* the thumb at one
 * end of the track: `Switch.StartContent` is revealed as the switch turns on and
 * `Switch.EndContent` as it turns off, each fading with the thumb's own travel, so
 * both are written once with no conditionals. The thumb is drawn last however the
 * children were ordered.
 *
 * **State works either way from one hook**: pass `isSelected` to control it, or
 * nothing and let it hold its own.
 *
 * `isInvalid` and `isDisabled` cascade in from an enclosing `Field`, so
 * `<Field isDisabled>` dims it with nothing said here — and an explicit prop still
 * wins, in either direction. Inside a `Field` the switch also hands its toggle
 * back up, so tapping a `Field.Label` or the description under it flips it.
 *
 * There is no `Switch.Label`: the track is a fixed pill and a label cannot sit
 * inside it, so the name is a `Field.Label` or a `ListGroup.ItemTitle` a row away.
 * A switch with no label anywhere near it needs an `accessibilityLabel`, the same
 * rule an icon-only `Button` follows.
 *
 * A haptic fires when a gesture actually flips it — never on the grab, since a
 * drag taken half way and released back has changed nothing. `haptic={false}`
 * silences it.
 *
 * @example
 * <Switch isSelected={isOn} onSelectedChange={setOn} />
 *
 * @example
 * <Field orientation="horizontal">
 *   <Field.Content>
 *     <Field.Label>Notifications</Field.Label>
 *     <Field.Description>Push alerts for new messages.</Field.Description>
 *   </Field.Content>
 *   <Switch color="success" isSelected={alerts} onSelectedChange={setAlerts} />
 * </Field>
 *
 * @example
 * <Switch defaultSelected size="lg">
 *   <Switch.StartContent>
 *     <Icon icon={IconCheckmark1Small} />
 *   </Switch.StartContent>
 *   <Switch.EndContent>
 *     <Icon icon={IconXmarkSmall} />
 *   </Switch.EndContent>
 * </Switch>
 */
export const Switch = Object.assign(SwitchRoot, {
	/** The knob. Composed in automatically; write it out to restyle it or fill it. */
	Thumb: SwitchThumb,
	/** Behind the thumb at the leading edge — revealed as the switch turns on. */
	StartContent: SwitchStartContent,
	/** Behind the thumb at the trailing edge — revealed as the switch turns off. */
	EndContent: SwitchEndContent,
	displayName: "DelacourUI.Switch",
});

import type { ReactNode } from "react";
import type { ViewProps } from "react-native";

/**
 * Props shared by `Switch.StartContent` and `Switch.EndContent`.
 *
 * The two are the same box at opposite ends of the track — only which end, and
 * which way their opacity runs, differ — so the type lives here rather than
 * twice. `style` is `Omit`ed because both carry an animated one of their own.
 */
export type SwitchContentProps = Omit<ViewProps, "children" | "style"> & {
	className?: string;
	children?: ReactNode;
};

import type { VariantProps } from "tailwind-variants";
import { tv } from "@registry/lib/tv";
import type { IconSize } from "@registry/ui/icon/icon.variants";

/** What a switch that is on means. Badge's, Checkbox's and Slider's set. */
export const SWITCH_COLORS = ["default", "primary", "success", "warning", "danger", "info"] as const;

export const SWITCH_SIZES = ["sm", "md", "lg"] as const;

export type SwitchColor = (typeof SWITCH_COLORS)[number];
export type SwitchSize = (typeof SWITCH_SIZES)[number];

/**
 * The axes a switch falls back to when nothing names one.
 *
 * Named once because two places read them — `defaultVariants` below and
 * {@link resolveSwitchAxes}, which runs before `tv` is ever called. A test pins
 * the pair, since a drift between them is a switch that renders at one size and
 * reports another.
 */
export const SWITCH_DEFAULT_COLOR: SwitchColor = "default";
export const SWITCH_DEFAULT_SIZE: SwitchSize = "md";

/**
 * The step every glyph on this control is drawn at — inside the knob, or at
 * either end of the track. One step rather than two, so a tick inside the thumb
 * and a tick behind it are the same mark. The `glyph` slot writes it out and a
 * test pins the two together.
 */
export const SWITCH_CONTENT_ICON_STEP: Record<SwitchSize, IconSize> = { sm: "xs", md: "sm", lg: "md" };

/**
 * How far the knob sits inside the track, on every side, in points.
 *
 * One number rather than two. Horizontally it is written into the `thumb`,
 * `startContent` and `endContent` slots as `left-0.75` / `right-0.75` and
 * subtracted twice by {@link switchTravel}, so a slot and this constant
 * disagreeing is a knob that stops short of the far edge at every size — a test
 * pins the class against it.
 *
 * Vertically it is never written at all. The track is `justify-center`, so an
 * absolutely positioned child with no vertical inset is centred by its parent —
 * `Slider`'s rule, where the track centres the thumb and the thumb carries no
 * offset of its own. On that axis this is a *relationship* a test pins,
 * `(track height − knob height) / 2`, rather than a value anything reads.
 *
 * It is also what makes the two capsules concentric: both are `rounded-full`, so
 * each radius is half its own height and the difference between them is exactly
 * this inset. That is the subtraction `Checkbox`'s fill makes against its
 * border, arrived at by construction rather than by a second number.
 *
 * Three rather than two because two left the knob looking wedged against the
 * ends — a rounded rectangle needs a little more air around it than a disc,
 * whose curve already reads as clearance.
 */
export const SWITCH_THUMB_INSET = 3;

/**
 * The spring the thumb settles on after a tap or a release.
 *
 * **Critically damped on purpose**, where every other spring in this package
 * overshoots a little. A wider thumb travels a shorter distance inside a track
 * that clips it, so an overshoot has nowhere to go: the knob would visibly
 * squash against the end of its own capsule on every toggle. A test pins the
 * damping ratio at or above one, so a retune cannot quietly reintroduce it.
 */
export const SWITCH_THUMB_SPRING = { damping: 26, mass: 0.4, stiffness: 400 } as const;

/**
 * The spring the whole control settles on when it is pressed and released.
 *
 * Deliberately `Pressable`'s own `PRESS_SPRING`: a switch responding to a touch
 * is the same event as a button responding to one, and two springs a frame apart
 * would read as two things happening. `Slider` copies it for the same reason.
 */
export const SWITCH_PRESS_SPRING = { damping: 18, mass: 0.4, stiffness: 320 } as const;

/**
 * How far the whole control shrinks while a finger is on it.
 *
 * The **track** scales, not the thumb — the track is the outermost node, so it
 * is the one thing `overflow-hidden` cannot clip, and scaling the knob inside a
 * capsule that crops it would take a bite out of the knob rather than acknowledge
 * the press. It is also the only press feedback this control has: until a drag
 * actually moves the thumb, nothing else says the touch landed.
 */
export const SWITCH_PRESS_ANIMATION = { restScale: 1, pressedScale: 0.96 } as const;

/**
 * How far a release may have travelled and still count as a tap, in points.
 *
 * A finger never leaves a control perfectly still, so "did not move" has to be a
 * tolerance rather than zero. Below it the release toggles whatever the state
 * was; above it the position and the velocity decide, and a drag that went out
 * and came back therefore commits nothing.
 */
export const SWITCH_TAP_SLOP = 4;

/**
 * The release speed that decides the outcome on its own, in points per second.
 *
 * A flick is a statement of intent: let go fast enough and the switch goes the
 * way the finger was going, however short of half way it stopped. Without it a
 * quick flick from the left edge would spring back, because the thumb never got
 * past the middle — the one case where position is the wrong question.
 */
export const SWITCH_FLING_VELOCITY = 500;

/**
 * Theme token the track fades **to** at each colour.
 *
 * `default` names `foreground` rather than `primary`, and the two are the same
 * value in this theme today — the situation `Badge` documents for its neutral
 * end and `Slider` repeats. `foreground` is the page's ink and `primary` is the
 * brand's action colour; collapsing them would be the drift, not the
 * duplication, since an app that re-themes `primary` to blue wants
 * `color="primary"` blue and `color="default"` still ink.
 */
export const SWITCH_TRACK_TOKEN: Record<SwitchColor, string> = {
	default: "foreground",
	primary: "primary",
	success: "success",
	warning: "warning",
	danger: "danger",
	info: "info",
};

/**
 * The track a switch that is off wears.
 *
 * `input` rather than `secondary`, and it is the token that makes the knob
 * legible without a border: it is the chrome a field's own box wears, a step
 * darker than the page in light and a step lighter in dark, so a knob painted
 * the page's own colour reads against it at either end of the theme. `secondary`
 * sits too close to the surface behind it for that.
 */
export const SWITCH_TRACK_REST_TOKEN = "input";

/** The track, on or off, once the switch is reporting an invalid value. */
export const SWITCH_INVALID_TRACK_TOKEN = "danger";

/**
 * Theme token the thumb fades **to** at each colour.
 *
 * Every entry is the `-foreground` of its own {@link SWITCH_TRACK_TOKEN} entry,
 * which is rule 11 doing its job: a single pale knob would be unreadable on
 * `warning`, whose foreground is near-black, so the knob follows the surface it
 * sits on. `default` is the exception the theme forces — there is no
 * `--color-foreground-foreground`, and `background` is what content drawn on the
 * page's ink actually is. A test pins the whole map against the track's rather
 * than trusting two tables to stay in step.
 */
export const SWITCH_THUMB_TOKEN: Record<SwitchColor, string> = {
	default: "background",
	primary: "primary-foreground",
	success: "success-foreground",
	warning: "warning-foreground",
	danger: "danger-foreground",
	info: "info-foreground",
};

/** The thumb a switch that is off wears. */
export const SWITCH_THUMB_REST_TOKEN = "background";

/** The thumb, on or off, once the switch is reporting an invalid value. */
export const SWITCH_INVALID_THUMB_TOKEN = "danger-foreground";

/** The colour a glyph inside `Switch.EndContent` takes — it sits on the *off* track. */
export const SWITCH_CONTENT_REST_TOKEN = "secondary-foreground";

/**
 * The `text-*` class a `Text` inside a content layer takes at each colour.
 *
 * A colour that has to reach a glyph is a token; a colour that has to reach a
 * `Text` is a class, because text colour goes on the `Text` and a `View` does
 * not cascade it (rule 1). So this map exists beside {@link SWITCH_THUMB_TOKEN}
 * rather than being derived from it: Tailwind's scanner is static, so a runtime
 * `text-${token}` is never compiled and would silently draw nothing. A test pins
 * every entry against the token it must agree with, which is the difference
 * between a coupling that is checked and one that is merely hoped for.
 */
export const SWITCH_CONTENT_TEXT_CLASS: Record<SwitchColor, string> = {
	default: "text-background",
	primary: "text-primary-foreground",
	success: "text-success-foreground",
	warning: "text-warning-foreground",
	danger: "text-danger-foreground",
	info: "text-info-foreground",
};

/** What a `Text` inside `Switch.EndContent` takes — it sits on the *off* track. */
export const SWITCH_CONTENT_REST_TEXT_CLASS = "text-secondary-foreground";

/** What either content layer takes once the switch is reporting an invalid value. */
export const SWITCH_INVALID_CONTENT_TEXT_CLASS = "text-danger-foreground";

/**
 * Styling for every part of a switch.
 *
 * One slotted `tv()` rather than a call per part, because `switch-thumb.tsx` and
 * the two content parts cannot import the root without closing a cycle
 * (AGENTS.md rule 3) yet all three read the same `size`.
 *
 * **It describes geometry, and almost no colour.** Every colour on this control
 * fades between two token *values* off the one `progress` — the track, the thumb
 * and both content layers — and a colour being interpolated cannot be a class,
 * which is the rule `Checkbox`'s border already follows. So there is no `color`
 * axis here at all: the maps above are where the colour lives, and the base
 * classes are only the resting appearance the animated styles start from. Adding
 * a `bg-*` per colour here would be a second source for one surface, which is
 * how a class and a style end up disagreeing for a frame on every toggle.
 *
 * **The track's height and the touch padding ride in the same size cell**,
 * because they are one number: they sum to 44pt at every size. Split them across
 * two variants and a retune of the track silently shrinks the target — the trap
 * `Slider` names, and a test asserts the sum rather than the parts.
 *
 * **The thumb is as wide as the track is tall, and shorter than it.** It is a
 * rounded rectangle lying on its side, not a disc — which is why it stopped
 * reading `--spacing-icon-*` and became plain spacing steps. That is the move
 * `Slider`'s handle already made, and for the same reason: the icon scale is
 * where a *glyph* belongs, and a knob is the body of the control rather than a
 * mark drawn on it. `Checkbox` still reads that scale because its square really
 * is a glyph in a box.
 *
 * Three relationships hold at every size and a test pins each, so the ladder can
 * be retuned without the test becoming a transcript of it: the thumb's width is
 * the track's height, its height is that less twice
 * {@link SWITCH_THUMB_INSET}, and the two capsules are therefore concentric.
 *
 * **The knob draws no border and no shadow.** A border is a second line drawn
 * where there is already a boundary — the knob is a solid block against a track
 * of a different colour — and against a saturated track it reads as a dark ring
 * rather than as definition. `Slider`'s handle dropped its own for the same
 * reason. Contrast at rest comes from the track's colour instead, which is why
 * {@link SWITCH_TRACK_REST_TOKEN} is `input`.
 *
 * **A content layer is as wide as the thumb's travel, not as wide as the
 * thumb.** It occupies exactly the space the knob vacates at its own end — which
 * is what the travel *is* — so the two layers and the thumb tile the track
 * instead of overlapping. Size them like the knob and they reach under it: the
 * far layer's text is then clipped by a knob drawn on top of it, visible only at
 * the size where the text is longest. They keep the thumb's *height*, so a glyph
 * at either end sits on the knob's own centre line.
 *
 * **Every slot that can hold a caller's content centres it.** The thumb and both
 * content layers are boxes a glyph is dropped into, and a `View` lays a child out
 * at flex-start by default — so a glyph in a knob that did not centre sits up
 * against its top-left corner, inside a circle, which reads as a mispositioned
 * icon rather than as a missing class. A test sweeps all three.
 *
 * **`overflow-hidden` on the track is load-bearing, not tidiness.** A caller's
 * `Switch.StartContent` is arbitrary content sitting inside a fully rounded
 * capsule, and without the clip a wide glyph paints over the track's own edge.
 * It is also why the thumb does **not** grow when grabbed the way a `Slider`'s
 * does: a scaled thumb would be clipped by the very same rule, and a knob
 * already following the finger does not need a second signal.
 *
 * **The fade lands on `touchArea`, the one slot no animated style touches.**
 * `track` and `thumb` both carry a `useAnimatedStyle`, and while neither writes
 * `opacity` today, a disabled treatment that would break the moment one did is a
 * treatment waiting to fail silently — the failure mode `Radio` records for a
 * class on `Pressable`'s own node.
 *
 * **`self-start` is load-bearing.** A switch is sized by its own geometry, and
 * inside a gap column every child is stretch-aligned by default — without it the
 * touch area spans the screen and a tap far from the pill toggles it.
 *
 * No slot worn by a `View` carries `text-*`; a glyph's colour is a token handed
 * to an `IconDefaultsProvider`. See AGENTS.md rule 1.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot
 * parse React Native's Flow-typed source. See AGENTS.md.
 */
export const switchVariants = tv({
	slots: {
		/** The transparent box the drag is claimed on. Padded on the cross axis only. */
		touchArea: "self-start items-center justify-center",
		/** The capsule. Its colour is an animated style, never a class. */
		track: "relative justify-center overflow-hidden rounded-full bg-input",
		/** The knob. Its position and its colour are one animated style. */
		thumb: "absolute left-0.75 items-center justify-center rounded-full bg-background",
		/** Behind the thumb at the leading edge. Revealed as the switch turns on. */
		startContent: "absolute left-0.75 items-center justify-center",
		/** Behind the thumb at the trailing edge. Revealed as the switch turns off. */
		endContent: "absolute right-0.75 items-center justify-center",
		/** Edge length any glyph on this control inherits — inside the knob, or at either end. */
		glyph: "",
		/** Handed to a `TextClassProvider`, never worn by a `View`. Its colour is added per end. */
		contentText: "font-semibold",
	},
	variants: {
		size: {
			sm: {
				touchArea: "py-2.5",
				track: "h-6 w-11",
				thumb: "h-4.5 w-6",
				startContent: "h-4.5 w-3.5",
				endContent: "h-4.5 w-3.5",
				glyph: "size-icon-xs",
				contentText: "text-[8px]",
			},
			md: {
				touchArea: "py-2",
				track: "h-7 w-13",
				thumb: "h-5.5 w-7",
				startContent: "h-5.5 w-4.5",
				endContent: "h-5.5 w-4.5",
				glyph: "size-icon-sm",
				contentText: "text-[10px]",
			},
			lg: {
				touchArea: "py-1",
				track: "h-9 w-17",
				thumb: "h-7.5 w-9",
				startContent: "h-7.5 w-6.5",
				endContent: "h-7.5 w-6.5",
				glyph: "size-icon-md",
				contentText: "text-[10px]",
			},
		},
		// The empty `false` branch is load-bearing typing, not a placeholder. `tv`
		// derives the prop type from the declared keys, so a map with only `true`
		// types the prop as `true` rather than `boolean`.
		isDisabled: { true: { touchArea: "opacity-50" }, false: {} },
	},
	defaultVariants: {
		size: SWITCH_DEFAULT_SIZE,
		isDisabled: false,
	},
});

/** What a switch was given at its own call site. */
export type SwitchOwnAxes = {
	color?: SwitchColor;
	size?: SwitchSize;
	isDisabled?: boolean;
	isInvalid?: boolean;
};

/** What an enclosing `Field` publishes, or null outside one. */
export type SwitchFieldAxes = { isDisabled?: boolean; isInvalid?: boolean };

/** Every axis settled, ready to hand to {@link switchVariants} and to context. */
export type SwitchAxes = {
	color: SwitchColor;
	size: SwitchSize;
	isDisabled: boolean;
	isInvalid: boolean;
};

/**
 * Settles a switch's axes from the two places they can come from.
 *
 * A two-rung ladder rather than `Checkbox`'s three, because there is no
 * `Switch.Group`: the switch's own props first, an enclosing `Field` last. A
 * switch inside a disabled `Field` dims with nothing said at the call site,
 * while `isDisabled={false}` still opts that one control out — `??` throughout
 * and never `||`, so an explicit `false` is a value rather than an absence.
 *
 * A `Field` reaches the two *state* axes only. It cannot acquire a paint axis by
 * accident, and a test pins that.
 *
 * Pure, so the whole matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveSwitchAxes({ own, field }: { own?: SwitchOwnAxes; field?: SwitchFieldAxes | null }): SwitchAxes {
	return {
		color: own?.color ?? SWITCH_DEFAULT_COLOR,
		size: own?.size ?? SWITCH_DEFAULT_SIZE,
		isDisabled: own?.isDisabled ?? field?.isDisabled ?? false,
		isInvalid: own?.isInvalid ?? field?.isInvalid ?? false,
	};
}

/** The two ends the track's colour interpolates between. */
export function resolveSwitchTrackTokens({ color, isInvalid }: { color: SwitchColor; isInvalid: boolean }): {
	rest: string;
	active: string;
} {
	if (isInvalid) return { rest: SWITCH_INVALID_TRACK_TOKEN, active: SWITCH_INVALID_TRACK_TOKEN };
	return { rest: SWITCH_TRACK_REST_TOKEN, active: SWITCH_TRACK_TOKEN[color] };
}

/**
 * The two ends the thumb's colour interpolates between.
 *
 * An **invalid** switch returns danger at both ends, on the track and on the
 * knob, so there is nothing to fade — the colour is the signal the value is
 * wrong, and it has to be there before the switch is turned on as much as after.
 * The precedence `Checkbox` sets on its border.
 */
export function resolveSwitchThumbTokens({ color, isInvalid }: { color: SwitchColor; isInvalid: boolean }): {
	rest: string;
	active: string;
} {
	if (isInvalid) return { rest: SWITCH_INVALID_THUMB_TOKEN, active: SWITCH_INVALID_THUMB_TOKEN };
	return { rest: SWITCH_THUMB_REST_TOKEN, active: SWITCH_THUMB_TOKEN[color] };
}

/**
 * Whether the caller wrote a `Switch.Thumb` of their own.
 *
 * The root composes one in when they did not, which is what makes `<Switch />`
 * on its own a complete control — `Radio`'s rule for its indicator, and for the
 * same reason: a switch has exactly one thumb, so it can know that a caller who
 * wrote none wants the default rather than an empty capsule.
 *
 * Takes an array of "is this child a thumb" rather than the children themselves,
 * so it stays free of React and reachable from `bun test` — the trade
 * `resolveIndicatorPlacement` already makes.
 */
export function hasThumbChild(isThumb: readonly boolean[]): boolean {
	return isThumb.some(Boolean);
}

/**
 * How far the thumb can travel, in points.
 *
 * A measured `0` means **not measured yet**, never "a track with no length", so
 * this is floored rather than allowed to go negative: the thumb sits at the
 * leading edge until both layouts have reported. `Slider` guards the same way.
 */
export function switchTravel({
	trackWidth,
	thumbWidth,
	inset,
}: {
	trackWidth: number;
	thumbWidth: number;
	/** {@link SWITCH_THUMB_INSET}. Taken off both ends. */
	inset: number;
}): number {
	"worklet";
	const travel = trackWidth - thumbWidth - inset * 2;
	return travel > 0 ? travel : 0;
}

/**
 * Where a release leaves the switch.
 *
 * Three questions in order, and the order is the design. A release whose finger
 * barely moved **in any direction** is a tap, so it toggles whatever the state
 * was — this is what lets one `Gesture.Pan()` serve both gestures rather than
 * racing a `Tap` against it. `distance` is deliberately not the along-track
 * translation: a vertical swipe that began on the switch moves nothing
 * horizontally, and reading only that axis would turn every attempt to scroll
 * past the control into a toggle. A release travelling fast is a **flick**, and
 * goes the way the finger was going however short of half way it stopped.
 * Anything else is settled by position.
 *
 * Marked `"worklet"` and written flat — it calls nothing, not even to clamp.
 * A module-scope worklet is rewritten into a factory call that runs at import
 * time in source order, so one calling a sibling works only while the sibling
 * happens to be declared first, and a tidy-up that reorders the file crashes the
 * UI thread. See AGENTS.md under **Slider**.
 *
 * Pure, so `bun test` reaches the whole matrix.
 */
export function resolveSwitchRelease({
	progress,
	distance,
	velocity,
	wasSelected,
}: {
	progress: number;
	/** How far the finger moved, in points, on whichever axis moved further. */
	distance: number;
	velocity: number;
	wasSelected: boolean;
}): boolean {
	"worklet";
	if (distance < SWITCH_TAP_SLOP) return !wasSelected;
	if (velocity > SWITCH_FLING_VELOCITY) return true;
	if (velocity < -SWITCH_FLING_VELOCITY) return false;
	return progress > 0.5;
}

/** Which end of the track a content layer sits at. */
export type SwitchContentPlacement = "start" | "end";

/**
 * The colour a content layer's glyphs and text take.
 *
 * The two ends sit on different surfaces, and that is the whole of the
 * decision: `Switch.StartContent` is revealed when the switch is **on**, so it
 * is drawn on the coloured track and takes that colour's `-foreground`;
 * `Switch.EndContent` is revealed when it is **off**, so it is drawn on the
 * resting track and takes `secondary`'s. Invalid outranks both, the precedence
 * `Checkbox` sets on its border.
 *
 * Returns a token for the glyph and a class for the text, because those are what
 * an `IconDefaultsProvider` and a `TextClassProvider` respectively take — the
 * asymmetry AGENTS.md's **Theming** section sets out.
 *
 * Pure, so `bun test` reaches the whole matrix.
 */
export function resolveSwitchContentTreatment({
	color,
	isInvalid,
	placement,
}: {
	color: SwitchColor;
	isInvalid: boolean;
	placement: SwitchContentPlacement;
}): { color: string; textClass: string } {
	if (isInvalid) return { color: SWITCH_INVALID_THUMB_TOKEN, textClass: SWITCH_INVALID_CONTENT_TEXT_CLASS };
	if (placement === "end") return { color: SWITCH_CONTENT_REST_TOKEN, textClass: SWITCH_CONTENT_REST_TEXT_CLASS };
	return { color: SWITCH_THUMB_TOKEN[color], textClass: SWITCH_CONTENT_TEXT_CLASS[color] };
}

export type SwitchVariantProps = VariantProps<typeof switchVariants>;
